<?php
namespace Tests\Feature;
use App\Models\AuditLog; use App\Models\Employee; use App\Models\Tenant; use App\Models\User; use Illuminate\Support\Str; use RuntimeException; use Tests\TestCase;
class AuditLogTest extends TestCase { public function test_model_changes_are_audited_and_audit_rows_are_immutable():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Audit '.Str::random(5)]);try{tenancy()->initialize($tenant);$u=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);$this->actingAs($u);$e=Employee::create(['name'=>'Before','national_id'=>'AUD-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active']);$e->update(['name'=>'After']);$log=AuditLog::where('auditable_type',Employee::class)->where('auditable_id',$e->id)->where('event','updated')->latest()->firstOrFail();$this->assertSame('After',$log->after['name']);$this->assertSame($u->id,$log->user_id);$this->expectException(RuntimeException::class);$log->delete();}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
